/bin/bash -lc "python3 - <<'PY'
from pathlib import Path

base = Path('/tmp/issue746-paths.txt')
paths = base.read_text(encoding='utf-8').splitlines()
meta_sections = {
    'MIPStarRE/LDT/Tactic/LdtSimpAttr.lean',
    'MIPStarRE/LDT/Tactic/QuantumNonneg.lean',
    'MIPStarRE/LDT/Tactic/AvgCongr.lean',
}
meta_imports = {
    ('MIPStarRE/LDT/Tactic/LdtSimpAttr.lean', 'import Mathlib.Tactic.Attr.Register'):
        'public meta import Mathlib.Tactic.Attr.Register',
    ('MIPStarRE/LDT/Tactic/AvgCongr.lean', 'import Lean.Elab.Tactic'):
        'public meta import Lean.Elab.Tactic',
}
aggregates = {'MIPStarRE/Quantum.lean'}

def module_doc_end(text: str) -> int:
    start = text.find('/-"'!'"')
    if start < 0:
        raise RuntimeError('missing module docstring')
    depth = 1
    i = start + 3
    while i < len(text) - 1:
        pair = text[i:i + 2]
        if pair == '/-':
            depth += 1
            i += 2
        elif pair == '-/':
            depth -= 1
            i += 2
            if depth == 0:
                return i
        else:
            i += 1
    raise RuntimeError('unterminated module docstring')

for path in paths:
    p = Path(path)
    old = p.read_text(encoding='utf-8')
    if old.startswith('module\\n'):
        raise RuntimeError(f'already converted: {path}')
    lines = old.splitlines(keepends=True)
    converted = []
    for line in lines:
        raw = line[:-1] if line.endswith('\\n') else line
        ending = '\\n' if line.endswith('\\n') else ''
        if raw.startswith('import '):
            raw = meta_imports.get((path, raw), 'public ' + raw)
        converted.append(raw + ending)
    new = 'module\\n\\n' + ''.join(converted)
    if path not in aggregates:
        end = module_doc_end(new)
        section = 'public meta section' if path in meta_sections else '@[expose] public section'
        new = new[:end] + '\\n\\n' + section + new[end:]
    p.write_text(new, encoding='utf-8')

print(f'converted {len(paths)} files')
print(f'meta sections: {len(meta_sections)}; aggregates: {len(aggregates)}')
PY

